class CandidateReplay { public static void main(String[] args) {
int u = 65536;
int v = 65536;
if (!((u >= 1 && u <= 1048576 && (u & (u - 1)) == 0) && (v >= 1 && v <= 1048576 && (v & (v - 1)) == 0))) { System.out.println("outside"); return; }
int result = 0;
Throwable failure = null;
try { result = org.apache.commons.math.util.MathUtils.gcd(u, v); } catch (Throwable t) { failure = t; }
System.out.println("admitted");
System.out.println(failure == null && (result == (u < v ? u : v)));
System.out.println(failure == null ? Long.toString(result) : "null");
System.out.println(failure == null ? "null" : ((char)34 + failure.getClass().getName() + (char)34));
} }
